\label{lem:pairtail}
Let \(0<b\leqslant1/2\), let \(r,s\) be nonnegative integers, and let \(Z\) be the sum of independent variables with laws \(\operatorname{Bin}(r,2b)\) and \(\operatorname{Bin}(s,b)\). If \(n=2r+s\) and \(t>n/2\) is an integer, then
\begin{equation}\label{eq:pairtail}
\mathbb P(Z\geqslant t)\leqslant\mathbb P(\operatorname{Bin}(n,b)\geqslant t).
\end{equation}

\label{lem:binomial}
For \(0\leqslant b\leqslant1/2\) and every positive integer \(d\),
\(\Phi_d(b)\leqslant b\).
Moreover, \(\Phi_{2j+1}(b)\) is nonincreasing in \(j\), and, for every integer \(j\geqslant0\),
\begin{equation}\label{eq:binomialdifference}
\Phi_{2j+1}(b)-\Phi_{2j+3}(b)
=\binom{2j+1}{j}[b(1-b)]^{j+1}(1-2b).
\end{equation}

\label{lem:survival}
Use the block sampling and deletion of Section~\ref{sec:sampling}
with any $0<b\leqslant1/2$ and any random collection $\mathcal M$ of
disjoint vertex pairs, retaining the notation $X,S_0,q_v$.
Then $S_0$ is majority-stable, every sink survives with probability
$b$, and every vertex $v$ of outdegree $d\geqslant1$ satisfies
$\mathbb P(v\in S_0)\geqslant L_{d,b}(q_v)$, where
\begin{equation}\label{eq:Ldq}
\begin{aligned}
L_{d,b}(q)={}&b(1-q)\,\mathbb P\bigl(\operatorname{Bin}(d,b)\leqslant\lfloor d/2\rfloor\bigr)+bq\,\mathbb P\bigl(\operatorname{Bin}(d-1,b)\leqslant\lfloor d/2\rfloor\bigr).
\end{aligned}
\end{equation}
For each $d\geqslant1$, the function $L_{d,b}$ is nondecreasing on $[0,1]$.

\label{lem:degreemin}
With \(b=4/9\) as above,
\begin{equation}\label{eq:cycleminimum}
\min_{d\geqslant1}L_d(1/3)=L_3(1/3)=p_C:=\frac{5740}{19683}.
\end{equation}

\label{prop:D2}
If \(\mathcal I\) is satisfiable, then \(\chi^*_{\mathrm{maj}}(D_2(\mathcal I))=3/2\). For every instance,
\begin{equation}\label{eq:D2soundness}
\chi^*_{\mathrm{maj}}(D_2(\mathcal I))\geqslant\frac9{6-\mu(\mathcal I)}.
\end{equation}
